-- Individually source-checked November 21, 2026 Pacific. No seed imports or copied photos.
begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name":"209 Handyman — Gutter Cleaning","city":"Service area only","phone":"(209) 427-5472","website":"https://209handyman.com/","source_url":"https://209handyman.com/gutter-cleaning/","areas":["Mountain House","Tracy","Lathrop","Manteca"],"tags":["gutter cleaning"],"description":"Advertises gutter debris removal and downspout checks, with Mountain House, Tracy, Lathrop and Manteca explicitly named on the gutter-cleaning page. The business describes itself as an unlicensed handyman; this listing covers the advertised cleaning service, not licensed construction or full gutter replacement. Confirm roof access, exact job scope, quote and dates directly. No visitor office established.","note":"First-party website information check November 21, 2026: identity, public phone, gutter-cleaning scope and individually named service cities. Business self-describes as unlicensed; no independent credential/legal eligibility, insurance, safety, quality or availability verification. No price or portfolio copied."},{"name":"Delta Bin Cleaner","city":"Service area only","phone":"(209) 640-0025","website":"https://www.deltabincleaner.com/","source_url":"https://www.deltabincleaner.com/","areas":["Tracy","Lathrop","Manteca"],"tags":["trash can cleaning","pressure washing"],"description":"Advertises trash can cleaning and residential pressure washing, explicitly serving Tracy, Lathrop and Manteca. Published plan prices contain conflicting one-time totals, so no price is adopted here. Confirm bin count, collection-day routing, exact address, subscription terms, quote and available dates directly. Mountain House coverage and a visitor office were not established.","note":"First-party website information check November 21, 2026: business name, public phone, advertised bin/pressure-washing services and named coverage cities. Email placeholder and conflicting $49/$50 one-time pricing omitted. No owner contact, credentials, workmanship, sanitation efficacy, appointment or rating verification; no images reused."},{"name":"Freddy’s Spotless Wash LLC","city":"Lodi","phone":"(209) 642-0000","website":"https://freddysspotlesswashllc.jobbersites.com/","source_url":"https://freddysspotlesswashllc.jobbersites.com/","areas":["Tracy","Lathrop","Manteca"],"tags":["pressure washing","gutter cleaning","trash can cleaning"],"description":"Lodi contact location; advertises exterior pressure washing, gutter cleaning and trash can cleaning. Its service-area list explicitly names Tracy, Lathrop and Manteca. Mountain House coverage is not established. Confirm the surface or bin type, access, materials, travel charges, quote and available dates directly; no public walk-in office established.","note":"First-party Jobber business website information check November 21, 2026: identity, public phone, Lodi contact-city, advertised services and explicitly named Tracy/Lathrop/Manteca coverage. Do not infer Mountain House from county coverage. Reviews, credentials, insurance, workmanship, sanitizing efficacy and availability not verified; no portfolio/review content reused."},{"name":"Golden State Bin Cleaning","city":"Service area only","phone":"(888) 922-4625","website":"https://goldenstatebincleaning.com/","source_url":"https://goldenstatebincleaning.com/","areas":["Mountain House","Tracy","Lathrop","Manteca"],"tags":["trash can cleaning"],"description":"Advertises residential and commercial trash can cleaning; its named service-area list includes Mountain House, Tracy, Lathrop and Manteca. Confirm your exact address, collection day, bin size, one-time or recurring plan terms, quote and available dates directly. No public visitor office or current route capacity established.","note":"First-party website information check November 21, 2026: identity, public phone, residential/commercial bin cleaning and individually named service cities. No owner confirmation, credential/insurance check, sanitation efficacy, workmanship, rating or appointment verification. Marketing germ-removal and environmental claims not adopted; no photos copied."}]'::jsonb) loop
if exists(select 1 from public.businesses where lower(rtrim(website,'/'))=lower(rtrim(r->>'website','/')) or right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10) or lower(name)=lower(r->>'name')) then raise exception 'Duplicate candidate: %',r->>'name';end if;
insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,needs_review,source,source_url,verification_source,verified_at)values(r->>'name','Home Services',r->>'city',null,r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,false,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now()) returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note)values(bid,r->>'source_url',array['identity','public phone','website','advertised services','explicit service cities','scope and limitations'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
select to_jsonb(b) into applied from public.businesses b where id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'CORE-01 individually first-party checked services; no owner availability or quality endorsement',r->>'source_url');end loop;end $curate$;
